def photo(name,alt,caption='',cls=''):
    # Consistent aspect ratios reserve layout before lazy image loading.
    return f'<figure class="editorial-photo {cls}"><img src="assets/brochure/{name}.webp" alt="{alt}" loading="lazy" width="900" height="700">'+(f'<figcaption>{caption}</figcaption>' if caption else '')+'</figure>'

def heading(kicker,title,id):
    return f'<div class="editorial-head"><p class="eyebrow">{kicker}</p><h2 class="display small" id="{id}" data-lines>{title}</h2></div>'

def gallery(items,cls=''):
    return '<div class="brochure-gallery '+cls+'" data-stagger>'+''.join(photo(name,label,label) for name,label in items)+'</div>'

