FOAM = '<section class="block editorial-dark" id="foam" aria-labelledby="foam-title"><div class="wrap">'+heading('POLIETILENE ESPANSO','Leggero sulla materia.<br><em>Attento ai dettagli.</em>','foam-title')+'''<div class="editorial-split"><div><p class="lead">Il foam è un polietilene espanso: flessibile e modellabile, si adatta a profili, superfici e oggetti. La sua struttura accompagna il prodotto nella movimentazione e nella protezione quotidiana.</p><p class="lead">La brochure lo presenta per la protezione antigraffio di mobili, vetro e ceramica, con caratteristiche di leggerezza, maneggevolezza, resistenza allo strappo e recupero della forma.</p><div class="material-properties" data-stagger><span>Flessibile</span><span>Non abrasivo</span><span>Leggero</span><span>Protettivo</span></div></div>'''+photo('foam-protezione-lampada','Lampada protetta dal foam, fotografia della brochure','La protezione segue la forma.','portrait-photo')+'''</div>'''+gallery([('foam-bicchiere-cristallo','Vetro e cristallo'),('foam-ceramica-protetta','Superfici delicate'),('foam-sfera-protetta','Forme da avvolgere'),('foam-struttura-impermeabilita','La struttura del materiale')])+'''<div class="material-note"><h3>Una materia versatile.</h3><p>La brochure descrive un materiale impermeabile, resistente agli sbalzi di temperatura e capace di assorbire e dissipare urti. La scelta di densità, spessore e lavorazione dipende dall’applicazione.</p></div></div></section>'''

CUSTOM_FOAM = '<section class="block tinted" aria-labelledby="custom-foam"><div class="wrap">'+heading('FORME, SPESSORI, ACCOPPIAMENTI','La protezione giusta<br>ha la <em>tua forma.</em>','custom-foam')+'''<div class="editorial-split"><p class="lead">Formati e dimensioni diversi, fino alla realizzazione di una fustella dedicata. Il foam può essere accoppiato con altri materiali per rispondere a esigenze differenti di protezione e confezionamento.</p><div class="material-list"><span>Polietilene a bassa e alta densità</span><span>Film metallizzati</span><span>Carta</span><span>Pellicole adesive</span><span>Film a bolle d’aria</span></div></div>'''+gallery([('foam-piatti','Piatti e ceramiche'),('foam-profilo-mobile','Profili per l’arredo'),('foam-dettaglio-ceramica','Dettagli da preservare'),('foam-serramento','Serramenti e profili'),('foam-pallone','Oggetti sagomati'),('foam-tessuto-protettivo','Fogli protettivi'),('foam-piatto-ceramica','Protezione delle superfici')])+'''</div></section>'''

