PSV = '<section class="block tinted" aria-labelledby="psv-meaning"><div class="wrap">'+heading('PLASTICA SECONDA VITA','Una filiera da conoscere.<br>Un contenuto da <em>tracciare.</em>','psv-meaning')+'''<div class="editorial-split"><div><p class="lead">Plastica Seconda Vita identifica prodotti ottenuti con materiale riciclato e ne rende riconoscibili origine e contenuto, nell’ambito del rispettivo schema di certificazione.</p><p class="lead">La presentazione descrive la tracciabilità, il calcolo del contenuto riciclato e la verifica indipendente. Richiama UNI UNIPLAST 10667, EN 15343 e UNI EN ISO 14021.</p></div><div><h3>Il ruolo di IPPR</h3><p class="lead">L’Istituto per la Promozione delle Plastiche da Riciclo, costituito da Unionplast, PlasticsEurope Italia e Corepla, mette in relazione domanda e offerta di prodotti riciclati e promuove la loro riconoscibilità, anche attraverso il repertorio dei prodotti.</p></div></div><div class="audience-grid" data-stagger><article><span>01</span><h3>Imprese</h3><p>Qualificare materiali e prodotti.</p></article><article><span>02</span><h3>Enti pubblici</h3><p>Individuare soluzioni per gli acquisti verdi.</p></article><article><span>03</span><h3>Persone</h3><p>Riconoscere il contenuto riciclato.</p></article><article><span>04</span><h3>Distribuzione</h3><p>Rispondere all’attenzione ambientale dei clienti.</p></article></div></div></section>'''

CAM = '<section class="block" aria-labelledby="cam-title"><div class="wrap">'+heading('ACQUISTI E AMBIENTE','Scegliere considerando<br><em>l’intero percorso.</em>','cam-title')+'''<div class="editorial-split"><div><h3>CAM e acquisti verdi</h3><p class="lead">I Criteri Ambientali Minimi considerano gli aspetti ambientali nelle diverse fasi di un acquisto. La presentazione li collega al Green Public Procurement: l’attenzione all’ambiente negli acquisti delle pubbliche amministrazioni.</p><p class="lead">Il tema va oltre il singolo materiale: progettazione, produzione, utilizzo, recupero e logistica concorrono a un approccio più circolare, con ricadute sulle filiere e sul territorio.</p><p class="source-note">La documentazione richiesta dipende dal prodotto e dalla specifica procedura di acquisto. La certificazione PSV non equivale da sola alla conformità a ogni criterio CAM.</p></div><div class="cam-art">'''+photo('ambiente-energia-risorse','Illustrazione su ambiente, energia e risorse dalla presentazione')+photo('cam-marchio','Simbolo dei Criteri Ambientali Minimi presente nella brochure')+'''</div></div></div></section>'''

CARBON = '<section class="block tinted" aria-labelledby="carbon-title"><div class="wrap">'+heading('GREEN CARBON FOOTPRINT','Misurare l’impatto.<br><em>Per migliorarlo.</em>','carbon-title')+'''<div class="editorial-split"><div class="carbon-measure">CO<sub>2</sub><span>equivalente</span></div><div><p class="lead">L’impronta climatica esprime in CO₂ equivalente le emissioni di gas serra associate, direttamente e indirettamente, a un prodotto, un’organizzazione o un servizio.</p><p class="lead">La brochure richiama la UNI EN ISO 14067:2018 per l’impronta climatica dei prodotti e le norme ISO 14040 e 14044 per la valutazione del ciclo di vita, o LCA.</p><p class="lead">Ridurre spessore, ingombro e impiego di materia è un obiettivo progettuale. Quantificare il beneficio ambientale richiede una valutazione riferita al prodotto e al suo ciclo di vita.</p><a class="text-link" href="protezioni.html#zero-title">Scopri Zerovirgolacinque <span>↗</span></a></div></div></div></section>'''

