TIGER_MORE = '<section class="block" aria-labelledby="tiger-project"><div class="wrap">'+heading('IL PROGETTO TIGER FILM','Tre linee.<br><em>La stessa direzione.</em>','tiger-project')+'''<div class="editorial-split"><div><p class="lead">Tiger Film dà un’identità ai progetti sviluppati da Imballaggi 2G sul tema della sostenibilità. La presentazione coinvolge l’intera filiera nella costruzione di un’economia circolare per gli imballaggi flessibili.</p><p class="lead">Le tre linee del certificato MixEco impiegano polietilene con contenuto di riciclato. L’allegato indica dimensioni variabili e colori neutro, colorato trasparente o colorato coprente.</p></div><div class="material-list"><span>Eco Converting · PE-LD</span><span>Eco Manuale · PE-LLD estensibile</span><span>Eco Automatico · PE-LLD estensibile</span></div></div>'''+gallery([('tiger-film-bobine-verde','Film per il confezionamento'),('tiger-film-bobine','Formati in bobina'),('tiger-film-bobina','La pellicola distesa'),('tiger-film-manuale','Confezionamento manuale')])+'''<details class="technical-data"><summary>Consulta l’allegato prodotti <span>+</span></summary><div class="annex-view">'''+photo('certificato-psv-allegato-prodotti','Allegato originale al certificato PSV 3040/2024 con gamma, percentuali e spessori')+'''<div><h3>Dati riferiti alle linee certificate.</h3><p>L’allegato riporta il contenuto totale riciclato e lo spessore minimo di ogni linea. Non specifica la ripartizione tra riciclato pre-consumo e post-consumo; le percentuali non vengono quindi attribuite a una delle due origini.</p><a class="text-link" href="assets/presentazione-plastica-seconda-vita.pdf#page=9" target="_blank" rel="noopener">Apri l’originale <span>↗</span></a></div></div></details></div></section>'''

COMPANY_MORE = '<section class="block" aria-labelledby="family-title"><div class="wrap">'+heading('DALLA BROCHURE AZIENDALE','Le persone.<br><em>Prima di tutto.</em>','family-title')+'''<div class="editorial-split">'''+photo('famiglia-giuri-storia','Fotografia storica aziendale tratta dalla brochure Imballaggi 2G','Dall’archivio della brochure aziendale.','portrait-photo')+'''<div><p class="lead">Il percorso di Aldo Giuri passa da una prima attività a una seconda realtà dedicata alla produzione di materiale plastico. È su queste basi che si sviluppa una visione più ampia del packaging, portata avanti dalla seconda generazione.</p><p class="lead">Cura del dettaglio, investimenti nella tecnologia, formazione continua e flessibilità nella gestione sono i punti su cui la brochure costruisce l’identità di Imballaggi 2G.</p><blockquote>Guardare al futuro<br>e progredire.</blockquote><p class="lead">Una gamma pensata per bisogni professionali diversi: retailer della grande distribuzione, alberghi, ristoranti, aziende private ed enti pubblici.</p><a class="text-link" href="contatti.html">Conosciamoci <span>↗</span></a></div></div></div></section>'''

CERT_MORE = '''<section class="block tinted" aria-labelledby="cert-scope"><div class="wrap">'''+heading('LEGGERE I DOCUMENTI','Il valore è anche<br>nella <em>precisione.</em>','cert-scope')+'''<div class="certificate-facts"><article><span>3040 / 2024</span><h3>PSV MixEco</h3><p>Commercializzazione di film in polietilene certificato PSV MixEco. Marchio con numero distintivo 5718; verifica e sorveglianza IIP.</p><dl><dt>Prima emissione</dt><dd>4 marzo 2024</dd><dt>Scadenza indicata</dt><dd>3 marzo 2027</dd></dl><a href="assets/certificato-film-3040-2024.pdf" target="_blank" rel="noopener">Certificato originale ↗</a></article><article><span>3433 / 2026</span><h3>PSV Sottoprodotto</h3><p>Produzione di coprispalla, coprisedia, buste e fogli protettivi, mediante taglio e saldatura con MPS da sottoprodotto esterno.</p><dl><dt>Numero distintivo</dt><dd>5718</dd><dt>Scadenza indicata</dt><dd>9 giugno 2029</dd></dl><a href="assets/certificato-coprispalla-3433-2026.pdf" target="_blank" rel="noopener">Certificato originale ↗</a></article></div><p class="source-note">Le scadenze sono quelle riportate nei documenti, salvo modifica, sospensione o revoca. La certificazione riguarda i prodotti nel relativo campo di applicazione.</p><details class="technical-data"><summary>Visualizza il certificato MixEco nella presentazione <span>+</span></summary>'''+photo('certificato-psv-3040-2024','Riproduzione del certificato PSV MixEco della presentazione aziendale','Certificato incluso nella presentazione, pagina 8.','certificate-image')+'''</details></div></section>'''

EXTRA = {
    'protezioni': BUBBLE+FOAM+CUSTOM_FOAM+XTRACELL+ZERO+APPLICATIONS,
    'sostenibilita': ECO+CIRCULAR+PSV+CAM+CARBON+PUGLIA+BIODIVERSITY+CERT_MORE,
    'bobine': TIGER_MORE,
    'azienda': COMPANY_MORE,
}

def enrich(key, body):
    if key == 'protezioni':
        hero, remaining = body.split('</section>', 1)
        gama, ending = remaining.split('</section>', 1)
        return hero+'</section>'+BUBBLE+gama+'</section>'+FOAM+CUSTOM_FOAM+XTRACELL+ZERO+APPLICATIONS+ending
    if key == 'sostenibilita':
        hero, remaining = body.split('</section>', 1)
        cert = remaining[remaining.index('<section class="block" aria-labelledby="so-cert">'):]
        return hero+'</section>'+ECO+CIRCULAR+PSV+PUGLIA+CAM+CARBON+BIODIVERSITY+cert+CERT_MORE
    return body+EXTRA.get(key,'')
